  calls.push([step, ...args]);
  if (step === failAt) throw failure;
};
const modules = {
  './store.js': {
    saveReport: async (...args) => record('save', ...args),
    loadReport: async (...args) => { record('load', ...args); return 'stored body'; }
  },
  './mail.js': { sendMail: async (...args) => record('mail', ...args) },
  './report_render.js': Object.fromEntries(['Daily', 'Weekly', 'Correction'].map(name => [
    "'`render${name}`, (...args) => { record('"'render', name, ...args); return "'`${name} HTML`; }
  ]))
